<div class="account-title"><h1>Profile</h1><p>Manage your account identity and password.</p></div>
<form method="post" class="billing-card"><?=csrf()?><input type="hidden" name="action" value="profile"><div class="field-card"><label>Name</label><input name="name" value="<?=h($user['name'])?>" required></div><div class="field-card" style="margin-top:16px"><label>Email</label><input value="<?=h($user['email'])?>" disabled></div><?php if(\App\Core\Auth::isPlatformAdmin((int)$user['id'])):?><div style="margin-top:16px"><span class="status-chip ready">Platform administrator</span></div><?php endif?><button class="btn dark" style="margin-top:18px">Save profile</button></form>

<form method="post" class="billing-card" style="margin-top:20px"><?=csrf()?><input type="hidden" name="action" value="password"><div><h2 style="margin-top:0">Change password</h2><p class="muted">Use at least 12 characters. For the seeded administrator account, change the temporary password after the first sign-in.</p></div><div class="field-card" style="margin-top:16px"><label>Current password</label><input type="password" name="current_password" autocomplete="current-password" required></div><div class="field-card" style="margin-top:16px"><label>New password</label><input type="password" name="new_password" autocomplete="new-password" minlength="12" required></div><div class="field-card" style="margin-top:16px"><label>Confirm new password</label><input type="password" name="confirm_password" autocomplete="new-password" minlength="12" required></div><button class="btn dark" style="margin-top:18px">Change password</button></form>
